import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [tasks, setTasks] = useState([]);

  const addTask = () => {
    const newTask = { id: Date.now(), text: "New Task", completed: false };
    setTasks([...tasks, newTask]);
  };

  const completeTask = (id) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, completed: true } : task
    ));
  };

  // Productivity score
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(task => task.completed).length;
  const productivityScore = totalTasks > 0 
    ? Math.round((completedTasks / totalTasks) * 100) 
    : 0;

  return (
    <div className="dashboard-container">
      <h1 className="dashboard-title">Welcome to Nityo Dashboard</h1>

      <div className="dashboard-card">
        <div className="emoji">✏️</div>
        <button className="action-btn" onClick={addTask}>Add Task</button>
      </div>

      <div className="dashboard-card">
        <div className="emoji">✅</div>
        {tasks.length > 0 ? (
          tasks.map(task => (
            <div key={task.id}>
              <span style={{ textDecoration: task.completed ? "line-through" : "none" }}>
                {task.text}
              </span>
              {!task.completed && (
                <button className="action-btn" onClick={() => completeTask(task.id)}>
                  Complete Task
                </button>
              )}
            </div>
          ))
        ) : (
          <p>No tasks yet</p>
        )}
      </div>

      <div className="dashboard-card">
        <div className="emoji">📊</div>
        <h3>Reports</h3>
        <p>Total Tasks: {totalTasks}</p>
        <p>Completed: {completedTasks}</p>
        <p>Productivity Score: {productivityScore}%</p>
        
        {/* Progress Bar */}
        <div className="progress-bar">
          <div 
            className="progress-fill" 
            style={{ width: `${productivityScore}%` }}
          ></div>
        </div>
      </div>

      <div className="dashboard-card">
        <div className="emoji">📅</div>
        <button className="action-btn">Manage Events</button>
      </div>

      <div className="dashboard-card">
        <div className="emoji">🌙☀️</div>
        <button
          className="action-btn"
          onClick={() => document.body.classList.toggle("dark-mode")}
        >
          Toggle Theme
        </button>
      </div>
    </div>
  );
}

export default Dashboard;
